INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('iso42001-a-2-2', 'ISO42001-A2', 'A.2.2', 'AI Policy', 'Document a formal AI policy, approved by management, that governs the responsible development and use of AI systems.', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('iso42001-a-2-3', 'ISO42001-A2', 'A.2.3', 'Alignment with Other Organisational Policies', 'Ensure the AI policy integrates with existing policies such as privacy, security, HR and quality.', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('iso42001-a-2-4', 'ISO42001-A2', 'A.2.4', 'Review of the AI Policy', 'Review and update the AI policy at planned intervals and whenever regulations or business circumstances change.', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('iso42001-a-3-2', 'ISO42001-A3', 'A.3.2', 'AI Roles and Responsibilities', 'Define, allocate and communicate roles and responsibilities for the AI management system.', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('iso42001-a-3-3', 'ISO42001-A3', 'A.3.3', 'Reporting of Concerns', 'Establish a confidential process for personnel to report ethical, safety or compliance concerns about AI systems.', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('iso42001-a-4-2', 'ISO42001-A4', 'A.4.2', 'Resource Documentation', 'Identify and document all resources required at each stage of the AI system lifecycle.', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('iso42001-a-4-3', 'ISO42001-A4', 'A.4.3', 'Data Resources', 'Document the data resources used by AI systems, including their intended use and limitations.', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('iso42001-a-4-4', 'ISO42001-A4', 'A.4.4', 'Tooling Resources', 'Identify and document the tooling resources used to develop, operate and maintain AI systems.', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('iso42001-a-4-5', 'ISO42001-A4', 'A.4.5', 'System and Computing Resources', 'Document the system and computing resources required by AI systems across their lifecycle.', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('iso42001-a-4-6', 'ISO42001-A4', 'A.4.6', 'Human Resources', 'Document the human resources and competencies needed to develop and operate AI systems responsibly.', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('iso42001-a-5-2', 'ISO42001-A5', 'A.5.2', 'AI System Impact Assessment Process', 'Establish a formal process for assessing the impacts of AI systems on individuals, groups and society.', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('iso42001-a-5-3', 'ISO42001-A5', 'A.5.3', 'Documentation of Impact Assessments', 'Document the results of AI system impact assessments and retain them for review.', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('iso42001-a-5-4', 'ISO42001-A5', 'A.5.4', 'Assessing Impact on Individuals or Groups', 'Assess potential consequences for individuals or groups of individuals affected by the AI system.', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('iso42001-a-5-5', 'ISO42001-A5', 'A.5.5', 'Assessing Societal Impacts', 'Assess the broader societal impacts of AI systems throughout their lifecycle.', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('iso42001-a-6-1-2', 'ISO42001-A6', 'A.6.1.2', 'Objectives for Responsible Development', 'Establish documented objectives for responsible development and integrate measures to achieve them.', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('iso42001-a-6-1-3', 'ISO42001-A6', 'A.6.1.3', 'Processes for Responsible Design and Development', 'Define and document processes for the responsible design and development of AI systems.', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('iso42001-a-6-2-2', 'ISO42001-A6', 'A.6.2.2', 'AI System Requirements and Specification', 'Document what the AI system must and must not do, including performance and constraint requirements.', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('iso42001-a-6-2-3', 'ISO42001-A6', 'A.6.2.3', 'Documentation of Design and Development', 'Record AI system design and development against objectives, requirements and specification criteria.', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('iso42001-a-6-2-4', 'ISO42001-A6', 'A.6.2.4', 'Verification and Validation', 'Define and apply verification and validation measures and criteria for AI systems.', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('iso42001-a-6-2-5', 'ISO42001-A6', 'A.6.2.5', 'AI System Deployment', 'Document a deployment plan and ensure requirements are met prior to deployment.', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('iso42001-a-6-2-6', 'ISO42001-A6', 'A.6.2.6', 'Operation and Monitoring', 'Plan for and perform ongoing oversight and monitoring of AI systems after deployment.', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('iso42001-a-6-2-7', 'ISO42001-A6', 'A.6.2.7', 'AI System Technical Documentation', 'Determine and provide the technical documentation needed by each relevant category of interested parties.', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('iso42001-a-6-2-8', 'ISO42001-A6', 'A.6.2.8', 'Recording of Event Logs', 'Record key events across the AI system lifecycle to support audit, traceability and explanation.', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('iso42001-a-7-2', 'ISO42001-A7', 'A.7.2', 'Data for Development and Enhancement', 'Define, document and implement data management processes for developing and enhancing AI systems.', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('iso42001-a-7-3', 'ISO42001-A7', 'A.7.3', 'Acquisition of Data', 'Document the sources of data and the legal basis for acquiring and using it.', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('iso42001-a-7-4', 'ISO42001-A7', 'A.7.4', 'Quality of Data for AI Systems', 'Define and measure data quality criteria for data used to build and operate AI systems.', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('iso42001-a-7-5', 'ISO42001-A7', 'A.7.5', 'Data Provenance', 'Record the provenance of data, tracking its origin and transformations (data lineage).', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('iso42001-a-7-6', 'ISO42001-A7', 'A.7.6', 'Data Preparation', 'Define and document criteria and methods for selecting and preparing data.', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('iso42001-a-8-2', 'ISO42001-A8', 'A.8.2', 'System Documentation and Information for Users', 'Provide clear instructions, capabilities and limitations so users can understand and operate the AI system.', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('iso42001-a-8-3', 'ISO42001-A8', 'A.8.3', 'External Reporting', 'Provide a channel for external interested parties to report problems and adverse impacts.', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('iso42001-a-8-4', 'ISO42001-A8', 'A.8.4', 'Communication of Incidents', 'Plan for and communicate AI system incidents, failures or breaches to relevant parties.', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('iso42001-a-8-5', 'ISO42001-A8', 'A.8.5', 'Information for Interested Parties', 'Determine and document obligations to report information about AI systems to interested parties.', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('iso42001-a-9-2', 'ISO42001-A9', 'A.9.2', 'Processes for Responsible Use', 'Define how the AI system should be operated day-to-day in line with policy.', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('iso42001-a-9-3', 'ISO42001-A9', 'A.9.3', 'Objectives for Responsible Use', 'Identify and record the objectives that guide the responsible use of AI systems.', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('iso42001-a-9-4', 'ISO42001-A9', 'A.9.4', 'Intended Use of the AI System', 'Ensure the AI system is used in accordance with its documented intended purpose, preventing mission creep.', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('iso42001-a-10-2', 'ISO42001-A10', 'A.10.2', 'Allocating Responsibilities', 'Clearly allocate responsibilities between the organisation, third parties and customers by contract.', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('iso42001-a-10-3', 'ISO42001-A10', 'A.10.3', 'Suppliers', 'Vet suppliers and contractually bind them to the organisation''s responsible-AI requirements.', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('iso42001-a-10-4', 'ISO42001-A10', 'A.10.4', 'Customers', 'Ensure the responsible approach to AI considers customer expectations and needs.', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('iso27001-a-5-1', 'ISO27001-A5', 'A.5.1', 'Policies for Information Security', 'Define, approve and communicate an information security policy set.', TRUE) ON CONFLICT (id) DO NOTHING;
