INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('iso27001-a-5-7', 'ISO27001-A5', 'A.5.7', 'Threat Intelligence', 'Collect and analyse threat intelligence to inform mitigation.', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('iso27001-a-5-8', 'ISO27001-A5', 'A.5.8', 'Information Security in Project Management', 'Integrate information security into project management.', TRUE) ON CONFLICT (id) DO NOTHING;
