INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('iso27001-a-5-10', 'ISO27001-A5', 'A.5.10', 'Acceptable Use of Information and Other Associated Assets', 'Define rules for acceptable use and handling of assets.', TRUE) ON CONFLICT (id) DO NOTHING;
