INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('iso27001-a-5-15', 'ISO27001-A5', 'A.5.15', 'Access Control', 'Establish rules to control physical and logical access to assets.', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('iso27001-a-5-16', 'ISO27001-A5', 'A.5.16', 'Identity Management', 'Manage the full lifecycle of identities.', TRUE) ON CONFLICT (id) DO NOTHING;
