INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('iso27001-a-5-18', 'ISO27001-A5', 'A.5.18', 'Access Rights', 'Provision, review, modify and remove access rights per policy.', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('iso27001-a-5-19', 'ISO27001-A5', 'A.5.19', 'Information Security in Supplier Relationships', 'Manage information security risks in supplier relationships.', TRUE) ON CONFLICT (id) DO NOTHING;
