INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('iso27001-a-5-21', 'ISO27001-A5', 'A.5.21', 'Managing Information Security in the ICT Supply Chain', 'Manage security risks across the ICT supply chain.', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO tenant_demo.controls (id, domain_id, ref, title, description, is_mandatory) VALUES ('iso27001-a-5-22', 'ISO27001-A5', 'A.5.22', 'Monitoring, Review and Change Management of Supplier Services', 'Monitor, review and manage changes to supplier services.', TRUE) ON CONFLICT (id) DO NOTHING;
